import subprocess, re, os
# all tracked + untracked (excluding .git)
tracked = subprocess.check_output(['git','ls-files'], text=True).splitlines()
try:
    untracked = subprocess.check_output(['git','ls-files','--others','--exclude-standard'], text=True).splitlines()
except Exception as e:
    untracked = []
print(f"tracked={len(tracked)} untracked={len(untracked)}")
for f in untracked: print(f"UNTRACKED: {f}")
pats = [
 ("AKIA", re.compile(r'AKIA[0-9A-Z]{16}')),
 ("github_token", re.compile(r'gh[pousr]_[A-Za-z0-9]{10,}|github_pat_[A-Za-z0-9_]{10,}')),
 ("https_github", re.compile(r'https://[^/\s:@]+@github\.com')),
 ("hf", re.compile(r'hf_[A-Za-z0-9]{10,}')),
 ("HF_TOKEN_assign", re.compile(r'HF_TOKEN\s*=\s*\S+')),
 ("AWSKEY_assign_nonempty", re.compile(r'AWS_(ACCESS_KEY_ID|SECRET_ACCESS_KEY)\s*=\s*["\']?([A-Za-z0-9/+=]{8,})')),
 ("AWS_env_assign", re.compile(r'os\.environ\["AWS_(ACCESS_KEY_ID|SECRET_ACCESS_KEY)"\]\s*=\s*".+?"')),
]
def mask_val(v):
    v=v.strip().strip("'\"")
    if len(v)<=8: return f"len={len(v)}"
    return f"len={len(v)} {v[:4]}...{v[-2:]}"
count=0
for f in tracked+untracked:
    if f.startswith('.git/'): continue
    try: sz=os.path.getsize(f)
    except: continue
    if sz>20_000_000: 
        print(f"SKIP-large: {f} {sz}");
        continue
    try:
        with open(f,'r',encoding='utf-8',errors='strict') as fh: text=fh.read()
    except: continue
    lines=text.splitlines()
    for i,line in enumerate(lines,1):
        for name,rx in pats:
            m=rx.search(line)
            if m:
                # skip known non-secrets
                if name=="AWSKEY_assign_nonempty":
                    val=m.group(2)
                    if val in ("access_key","secret_key","{access_key}","{secret_key}") or val.startswith("{") or val.startswith("$"):
                        break
                    if ">>" in val or "~/.bashrc" in val:
                        pass
                if name=="HF_TOKEN_assign":
                    if "<your" in line or "HF_TOKEN=" not in line: pass
                print(f"{f}:{i} [{name}] val~{mask_val(m.group(0)[-60:])}")
                count+=1
                break
print(f"TOTAL_HITS={count} DONE")
